#include "market_comparison_composite.hpp"
#include "quant_research_model.hpp"
#include <QJsonDocument>
#include <QCryptographicHash>
#include <QRegularExpression>
#include <QSet>
#include <cmath>
#include <algorithm>
namespace marketComparison::composite {
namespace {
void need(bool ok,QString why){if(!ok)throw std::runtime_error(why.toUtf8().constData());}
QString hash(QByteArray bytes){return QString::fromLatin1(QCryptographicHash::hash(bytes,QCryptographicHash::Sha256).toHex());}
bool code(QString s){return QRegularExpression("^[0-9]{6}$").match(s).hasMatch();}
void codes(const QJsonArray&input){need(input.size()>=1&&input.size()<=10000,"当前完整成分数须为1–10000");QSet<QString>seen;for(auto v:input){need(v.isString()&&code(v.toString())&&!seen.contains(v.toString()),"成分代码缺失、重复或不明确");seen.insert(v.toString());}}
}
QJsonObject definition(const QJsonObject&d){auto tax=d.value("taxonomy").toString(),node=d.value("code").toString();QString pattern=tax=="industry"?"^(sw2_[0-9]+|new_[a-z0-9_]+)$":tax=="concept"?"^(chgn_[0-9]+|gn_[a-z0-9_]+)$":tax=="region"?"^diyu_[0-9]+$":"(?!)";need(QRegularExpression(pattern).match(node).hasMatch()&&d.value("provider")=="sina-public-"+tax&&d.value("providerId")==node&&d.value("key")=="sina-"+tax+":"+node&&!d.value("name").toString().trimmed().isEmpty()&&d.value("name").toString().size()<=160,"新浪板块节点/来源/分类身份不匹配，未按同名猜测");return {{"key",d["key"]},{"name",d["name"]},{"taxonomy",tax},{"code",node},{"provider",d["provider"]},{"providerId",node},{"kind","composite-estimate"},{"historyMode",historyMode}};}
QJsonObject identity(const QJsonObject&data){need(data["adjustmentMode"]=="forward-adjusted","当前成分估算只接受明确前复权本机数据");quantResearch::readBars(data);auto date=QDate::fromString(data["asOf"].toString(),Qt::ISODate);need(date<=QDateTime::currentDateTimeUtc().toOffsetFromUtc(28800).date(),"前复权数据截止日期来自未来");return {{"datasetId",data["datasetId"]},{"sha256",hash(QJsonDocument(data).toJson(QJsonDocument::Compact))},{"asOf",data["asOf"]},{"adjustmentMode",data["adjustmentMode"]},{"source",data["source"]},{"membershipMode",data["membershipMode"]}};}
QJsonArray datasets(const QByteArray&bytes){auto root=quantResearch::parse(bytes);QJsonArray out;QSet<QString>seen;if(root["schema"]=="quant-native-dataset/v1"){identity(root);out.append(root);return out;}need(root["schema"]=="quant-native-workspace/v1"&&root["records"].isArray(),"需要原生前复权数据包或既有量化库");for(auto v:root["records"].toArray()){auto row=v.toObject();if(row["kind"]!="dataset")continue;auto raw=row["rawUtf8"].toString().toUtf8();auto original=quantResearch::importText(raw);need(original["id"]==row["id"]&&original["original"]==row["original"]&&!seen.contains(row["id"].toString()),"量化数据原文字节/摘要/记录不一致");seen.insert(row["id"].toString());auto data=original["original"].toObject();if(data["adjustmentMode"]=="forward-adjusted"){identity(data);out.append(data);}}return out;}
int count(const QByteArray&bytes){need(bytes.size()>0&&bytes.size()<=4096,"成分数量响应为空或超限");auto text=QString::fromUtf8(bytes).trimmed();QJsonParseError error;auto doc=QJsonDocument::fromJson(bytes,&error);if(error.error==QJsonParseError::NoError&&doc.isObject()){auto v=doc.object()["data"];text=v.isDouble()?QString::number(v.toDouble(),'g',17):v.toString();}if(text.startsWith('"')&&text.endsWith('"'))text=text.mid(1,text.size()-2);need(QRegularExpression("^[0-9]+$").match(text).hasMatch(),"新浪成分数量不是正整数");bool ok=false;auto n=text.toInt(&ok);need(ok&&n>=1&&n<=10000,"新浪成分数量超过1–10000边界");return n;}
QJsonArray members(const QByteArray&bytes,int pageRows,const QJsonArray&prior){need(bytes.size()<=1024*1024,"成分页超过1MiB");QJsonParseError e;auto doc=QJsonDocument::fromJson(bytes,&e);need(e.error==QJsonParseError::NoError,"新浪成分页JSON无效");auto input=doc.isArray()?doc.array():doc.object()["data"].toArray();need(pageRows>=1&&pageRows<=80&&input.size()==pageRows,"新浪成分页数量不完整");QJsonArray out=prior;QSet<QString>seen;for(auto v:prior)seen.insert(v.toString());for(auto v:input){need(v.isObject(),"成分记录不是对象");auto row=v.toObject();QString c=row["code"].toString(),symbol=row["symbol"].toString();auto match=QRegularExpression("^(sh|sz|bj)([0-9]{6})$").match(symbol);if(c.isEmpty()&&match.hasMatch())c=match.captured(2);need(code(c)&&(symbol.isEmpty()||(match.hasMatch()&&match.captured(2)==c))&&!seen.contains(c),"成分代码重复、非法或与symbol冲突");seen.insert(c);out.append(c);}codes(out);return out;}
QJsonObject build(const QJsonObject&data,const QJsonArray&requested,int rawDays,const QDateTime&cutoff){auto metadata=identity(data);need(cutoff.isValid()&&data["asOf"].toString()<=cutoff.toOffsetFromUtc(28800).date().toString(Qt::ISODate),"基线超过估算截止时刻");need(rawDays>=2&&rawDays<=1601,"估算窗口须为2–1601");codes(requested);auto all=quantResearch::readBars(data);QMap<QString,QMap<QString,double>> included;QJsonArray includedCodes;QSet<QString>dateSet;for(auto v:requested){auto c=v.toString();auto rows=all.value(c);if(rows.size()<2)continue;QMap<QString,double>points;for(auto b:rows){points[b.date]=b.close;dateSet.insert(b.date);}included.insert(c,points);includedCodes.append(c);}need(included.size()>=2,"可用成分历史少于2只，无法计算板块等权估算");auto dates=dateSet.values();std::sort(dates.begin(),dates.end());int minimum=std::max(2,int(std::ceil(included.size()*.6)));QList<QPair<QString,double>> returns;QJsonArray coverage;for(int n=1;n<dates.size();++n){int count=0;double sum=0;for(auto points:included)if(points.contains(dates[n])&&points.contains(dates[n-1])){double r=points.value(dates[n])/points.value(dates[n-1])-1;if(std::isfinite(r)){sum+=r;++count;}}coverage.append(QJsonObject{{"date",dates[n]},{"count",count},{"minimum",minimum}});if(count>=minimum)returns.append({dates[n],sum/count});}returns=returns.mid(std::max(0,int(returns.size())-rawDays-1));need(returns.size()>=2,"满足成分覆盖阈值的共同交易日不足");double level=100;QJsonArray points;for(auto item:returns){level*=1+item.second;need(std::isfinite(level)&&level>0,"等权连乘结果无效");points.append(QJsonObject{{"date",item.first},{"close",std::round(level*1e8)/1e8}});}int missing=requested.size()-includedCodes.size();QJsonArray warnings{"这是当前成分等权估算，不是供应商板块指数，也不是同花顺原始指数。","当前成分口径存在幸存者偏差，不能用于证明历史时点真实成分表现。"};if(missing)warnings.append(QString("本地基线缺少 %1 只当前成分，已按每日覆盖阈值计算。").arg(missing));return {{"points",points},{"requestedConstituents",requested.size()},{"includedConstituents",includedCodes.size()},{"minimumDailyCoverage",minimum},{"includedCodes",includedCodes},{"dailyCoverage",coverage},{"dataset",metadata},{"source","local-current-constituent-equal-weight"},{"sourceLabel","本地前复权 · 当前完整成分等权估算"},{"sourceUrl","stock-local-dataset:///"+metadata["sha256"].toString()},{"historyMode",historyMode},{"synthetic",true},{"survivorshipBias",true},{"warnings",warnings},{"partial",missing>0},{"coverageDenominator","included-local-constituents"}};}
}
